SourceCode.Declaration:
/// <summary>
/// Extension of CustRecurrenceInvoiceDataContract to add "Use system date for recurrence" toggle
/// and apply system date when toggle is enabled. Standard class is not modified.
/// </summary>
[ExtensionOf(classStr(CustRecurrenceInvoiceDataContract))]
internal final class METCustRecurrenceInvoiceDataContract_Extension
{
    public boolean useSystemDateForRecurrence;

}

Method.Source:
/// <summary>
/// Initialize default values for extension parameter
/// </summary>
public void initialize()
{
    next initialize();

    // Default to false,not forcing system date unless user enables the toggle
    this.parmUseSystemDateForRecurrence(false);
}

[DataMemberAttribute,
    SysOperationLabelAttribute(literalstr("Use system date for recurrence")),
    SysOperationHelpTextAttribute(literalstr("If enabled, recurrence scheduling in the batch job considers both dates as the system date.")),
    SysOperationDisplayOrderAttribute('2')]
public boolean parmUseSystemDateForRecurrence(boolean _useSystemDateForRecurrence = useSystemDateForRecurrence)
{
    useSystemDateForRecurrence = _useSystemDateForRecurrence;

    return useSystemDateForRecurrence;
}

/// <summary>
/// If toggle enabled, override the invoice and generation dates to system date before validation.
/// </summary>
public boolean validate()
{
    if (this.parmUseSystemDateForRecurrence())
    {
        TransDate systemDate = DateTimeUtil::getSystemDate(DateTimeUtil::getUserPreferredTimeZone());

        // Use existing parm methods to set the dates (do not access internal fields directly)
        this.parmRecurrenceInvoiceDate(systemDate - 1);
        this.parmRecurrenceGenerationDate(systemDate - 1);

        Info(strFmt(" Validate - Invoice date: %1, Generation date %2", this.parmRecurrenceInvoiceDate(), this.parmRecurrenceGenerationDate()));
    }

    return next validate();
}
